import json,subprocess
def pair(m,start,end):
    r=subprocess.run(['python3','ia_cli.py','compare','--metrics',m+','+m,'--start',start,'--end',end],capture_output=True,text=True)
    try:
        d=json.loads(r.stdout)
    except Exception:
        return {'err':r.stdout[:200]}
    if not d.get('ok'): return {'rc':'not ok','status':str(d.get('data',{}))[:150]}
    sides=d.get('data',{}).get('sides',[])
    if not sides: return {'err':'no sides'}
    ic=sides[0].get('interval_change_common_window',{})
    return {'metric':m,'basis':ic.get('basis_date'),'basis_v':ic.get('basis_value'),'end':ic.get('end_date'),'end_v':ic.get('end_value'),'pct':ic.get('pct_change'),'pp':ic.get('pp_change'),'bp':ic.get('bp_change')}
for m in ['USDJPY','UST_2Y','SPX','DXY','GOLD_F','NIKKEI225','DAX','SHCOMP','VIX','EURUSD','USDCNY']:
    print(json.dumps(pair(m,'2025-11-20','2026-11-20'),ensure_ascii=False))
