import json
import subprocess

def hist(m):
    r = subprocess.run(['python3', 'ia_cli.py', 'history', '--metric', m],
                       capture_output=True, text=True)
    return json.loads(r.stdout).get('data', {}).get('series', {})

import bisect

def month_last_obs(ser, ym):
    dates, values = ser['dates'], ser['values']
    i = bisect.bisect_right(dates, ym + '-31')
    j = i - 1
    while j >= 0 and values[j] is None:
        j -= 1
    return (dates[j], values[j]) if j >= 0 else (None, None)

def ym_shift(ym, k):
    y, m = int(ym[:4]), int(ym[5:7])
    t = y * 12 + (m - 1) + k
    return f'{t//12:04d}-{t%12+1:02d}'

series = {}
for m in ['SPX', 'UST_10Y', 'DXY', 'GOLD_F', 'VIX', 'NIKKEI225', 'CURVE_2S10S']:
    series[m] = hist(m)

for anchor in ['2025-03', '2022-06', '2023-10', '2021-02', '2019-12']:
    print('==', anchor)
    for m in ['SPX', 'UST_10Y', 'DXY', 'GOLD_F']:
        ser = series[m]
        d0, v0 = month_last_obs(ser, anchor)
        row = []
        for k in (3, 6, 12):
            tgt = ym_shift(anchor, k)
            d1, v1 = month_last_obs(ser, tgt)
            if v0 is None or v1 is None:
                row.append(f'{k}m:NA')
                continue
            if m == 'UST_10Y':
                row.append(f'{k}m:{v1-v0:+.2f}pp({d0}→{d1})')
            else:
                row.append(f'{k}m:{(v1/v0-1)*100:+.2f}%({d0}→{d1})')
        print(f'  {m:8s} v0={v0}@{d0}', ' '.join(row))

